function layoutOf(u){
  const f = UNIT_LAYOUT_FILES[u.unit];
  if (f) return { code: f.code || layoutFor(u), src: f.src };
  const code = layoutFor(u);
  return code && STANDARD_LAYOUTS[code] ? { code, src: STANDARD_LAYOUTS[code].src } : null;
}

function layoutFor(u){
  if (LAYOUT_BY_UNIT[u.unit]) return LAYOUT_BY_UNIT[u.unit];
  const m = /([A-E])(\d{2})$/.exec(u.unit);
  if (!m) return null;
  const [, tower, line] = m, n = parseInt(line, 10), a = u.sqm;
  if (tower === "E") return n === 10 ? null : "1BR-D";
  if (tower === "A") return a < 33 ? "STU-B3" : a > 40 ? "1BR-B1" : null;
  if (a <= 23.5) return "STU-C";
  if (a <= 28) return "STU-A1";
  return null;
}

